import {
  ChangeDetectionStrategy, Component, ViewEncapsulation, computed, input, output,
} from '@angular/core';
import { HrmAlert, HrmProgress } from 'hrm-ui';

/**
 * @file Form Design System — phần LAYOUT còn thiếu: `table` · `checklist` · điều hướng section.
 *
 * Bổ sung cho `_form-ds.ts` (shell · grid · section · field · repeatable · các trait).
 * Cùng một triết lý: form KHÔNG phân loại theo tên nghiệp vụ mà theo **Layout × Trait**.
 * Nghiệp vụ mới = chọn 1 layout + N trait ⇒ thêm cấu hình, KHÔNG thêm component.
 *
 * Ba component ở đây:
 *   - `VnrEditableFormTable` — layout `table`: nhập nhiều dòng dạng bảng (grid nhập liệu).
 *   - `VnrChecklistGroup`    — layout `checklist`: onboarding / offboarding / bàn giao.
 *   - `VnrFormSectionNav`    — điều hướng giữa các section của form dài.
 *
 * SỐ CỘT / CÁCH ĐỔ LAYOUT bám **bề rộng container** (CSS Container Queries), KHÔNG bám
 * tên chế độ mở (bảng+chi tiết / cạnh danh sách / giữa màn hình / toàn trang / tab mới).
 * Các component này đặt bên trong `vnr-form-shell` để hưởng container-name `vnrform`.
 *
 * RANH GIỚI KIẾN TRÚC (chung cho cả file): KHÔNG tính tiền, KHÔNG tính ngày/hạn mức,
 * KHÔNG tự quyết hợp lệ hay không. Component nhận giá trị ĐÃ TÍNH và bắn event ra để
 * tầng nghiệp vụ tính lại rồi đẩy xuống. Chỉ ĐẾM và ĐỊNH DẠNG để hiển thị.
 *
 * File này là ỨNG VIÊN để chuyển lên `libs/hrm-ui` sau khi nghiệm thu trên template.
 */

// ══════════════════════════════════════════════════════════════════════════════
// LAYOUT · table — lưới nhập liệu nhiều dòng
// ══════════════════════════════════════════════════════════════════════════════

/** Kiểu dữ liệu ô — quyết định control nhập và cách căn lề mặc định. */
export type VnrFormTableColumnType = 'text' | 'number';

/** Căn lề ô. Cột số mặc định căn phải để so sánh được bằng mắt. */
export type VnrFormTableAlign = 'start' | 'end';

/** Giá trị một ô — chuỗi, số, hoặc rỗng. */
export type VnrFormTableCellValue = string | number | null;

export interface VnrFormTableColumn {
  /** Khoá ô trong `VnrFormTableRow.cells` — cũng là khoá khớp với `VnrFormTableTotal.key`. */
  readonly key: string;
  readonly label: string;
  /** Bề rộng cột: số ⇒ px, chuỗi ⇒ giá trị CSS bất kỳ. Bỏ trống ⇒ tự co. */
  readonly width?: string | number | null;
  /** Bỏ trống ⇒ suy từ `type` (number ⇒ 'end', còn lại ⇒ 'start'). */
  readonly align?: VnrFormTableAlign;
  /** Cột chỉ đọc — vd cột "Thành tiền" do tầng nghiệp vụ tính sẵn. */
  readonly readonly?: boolean;
  readonly type?: VnrFormTableColumnType;
}

export interface VnrFormTableRow {
  readonly id: string;
  /** Giá trị từng ô, khoá theo `VnrFormTableColumn.key`. */
  readonly cells: Record<string, VnrFormTableCellValue>;
  /** Lỗi của cả dòng — do tầng nghiệp vụ kiểm tra rồi truyền vào. */
  readonly error?: string | null;
}

/** Dòng tổng — giá trị ĐÃ TÍNH bên ngoài, UI tuyệt đối không cộng. */
export interface VnrFormTableTotal {
  /** Khớp `VnrFormTableColumn.key` để rơi đúng cột. */
  readonly key: string;
  readonly value: VnrFormTableCellValue;
}

export interface VnrFormTableCellChange {
  readonly rowId: string;
  readonly key: string;
  readonly value: VnrFormTableCellValue;
}

/**
 * Lưới nhập liệu nhiều dòng (layout `table`).
 *
 * RÀNG BUỘC KIẾN TRÚC (thực thi bằng THIẾT KẾ, không bằng lời nhắc): component này
 * KHÔNG cộng tổng, KHÔNG nhân số lượng × đơn giá, KHÔNG suy ra dòng nào sai.
 * Nó nhận `rows` + `totals` ĐÃ TÍNH và bắn `cellChange` để tầng business-rule tính lại.
 * ⇒ Dùng lại được cho: chấm công theo ngày · phân bổ ngân sách · định biên · KPI theo kỳ ·
 *   danh sách người tham gia · bảng lương chi tiết · nhập điểm đánh giá.
 *
 * Container hẹp ⇒ tự đổ về dạng THẺ (vẫn nhập được), không cuộn ngang.
 */
@Component({
  selector: 'vnr-editable-form-table',
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  template: `
    <div class="vnr-eft">
      <table class="vnr-eft__tb">
        <thead>
          <tr>
            <th class="ix">#</th>
            @for (c of columns(); track c.key) {
              <th [attr.data-align]="alignOf(c)" [style.inline-size]="widthOf(c)">{{ c.label }}</th>
            }
            <!-- aria-label thay cho chữ ẩn: cột này không có tiêu đề nhìn thấy được, nhưng để trống
                 thì trình đọc màn hình đọc ô cuối mỗi dòng là "cột trống". Dùng aria-label thay vì
                 span .sr-only vì file này là ứng viên chuyển lên libs/hrm-ui (nơi không có Tailwind). -->
            @if (!readonly()) { <th class="ac" aria-label="Thao tác trên dòng"></th> }
          </tr>
        </thead>
        <tbody>
          @for (r of rows(); track r.id; let i = $index) {
            <tr [class.has-err]="!!r.error">
              <td class="ix">{{ i + 1 }}</td>
              @for (c of columns(); track c.key) {
                <td [attr.data-align]="alignOf(c)">
                  @if (readonly() || c.readonly) {
                    <span class="vnr-eft__ro">{{ display(r, c) }}</span>
                  } @else {
                    <!-- Nhãn KÈM SỐ DÒNG: bảng nhiều dòng mà chỉ đọc "Số lượng" thì người dùng
                         trình đọc màn hình không biết đang ở dòng nào. -->
                    <input class="vnr-eft__in" [attr.data-align]="alignOf(c)"
                      [type]="c.type === 'number' ? 'number' : 'text'"
                      [value]="raw(r, c.key)" [attr.aria-label]="c.label + ', dòng ' + (i + 1)"
                      (change)="onCell(r.id, c, $event)" />
                  }
                </td>
              }
              @if (!readonly()) {
                <td class="ac">
                  <button type="button" class="vnr-eft__b" [title]="'Nhân bản dòng ' + (i + 1)"
                    [attr.aria-label]="'Nhân bản dòng ' + (i + 1)" (click)="duplicateRow.emit(r.id)">⧉</button>
                  <button type="button" class="vnr-eft__b is-danger" [title]="'Xoá dòng ' + (i + 1)"
                    [attr.aria-label]="'Xoá dòng ' + (i + 1)" (click)="removeRow.emit(r.id)">✕</button>
                </td>
              }
            </tr>
            @if (r.error) {
              <!-- Dòng lỗi: tô nền KÈM CHỮ lỗi — không chỉ dựa vào màu -->
              <tr class="vnr-eft__er">
                <td [attr.colspan]="colSpan()">{{ r.error }}</td>
              </tr>
            }
          } @empty {
            <tr><td class="vnr-eft__empty" [attr.colspan]="colSpan()">{{ emptyText() }}</td></tr>
          }
        </tbody>
        @if (totals().length) {
          <tfoot>
            <tr>
              <td class="ix"></td>
              @for (c of columns(); track c.key; let first = $first) {
                <td [attr.data-align]="alignOf(c)">
                  @if (totalOf(c.key) !== null) { <b class="tv">{{ fmt(totalOf(c.key)) }}</b> }
                  @else if (first) { <span class="tl">{{ totalLabel() }}</span> }
                </td>
              }
              @if (!readonly()) { <td class="ac"></td> }
            </tr>
          </tfoot>
        }
      </table>

      <!-- Thẻ thay thế khi container hẹp — VẪN NHẬP ĐƯỢC, cùng dữ liệu, không cuộn ngang -->
      <div class="vnr-eft__cards">
        @for (r of rows(); track r.id; let i = $index) {
          <div class="vnr-eft__card" [class.has-err]="!!r.error">
            <div class="hd">
              <span class="ix">{{ i + 1 }}</span>
              <span class="sp"></span>
              @if (!readonly()) {
                <button type="button" class="vnr-eft__b" [attr.aria-label]="'Nhân bản dòng ' + (i + 1)"
                  (click)="duplicateRow.emit(r.id)">Nhân bản</button>
                <button type="button" class="vnr-eft__b is-danger" [attr.aria-label]="'Xoá dòng ' + (i + 1)"
                  (click)="removeRow.emit(r.id)">✕</button>
              }
            </div>
            <div class="bd">
              @for (c of columns(); track c.key) {
                <label class="fl">
                  <span class="lb">{{ c.label }}</span>
                  @if (readonly() || c.readonly) {
                    <span class="vnr-eft__ro" [attr.data-align]="alignOf(c)">{{ display(r, c) }}</span>
                  } @else {
                    <input class="vnr-eft__in" [attr.data-align]="alignOf(c)"
                      [type]="c.type === 'number' ? 'number' : 'text'"
                      [value]="raw(r, c.key)" (change)="onCell(r.id, c, $event)" />
                  }
                </label>
              }
            </div>
            @if (r.error) { <div class="er">{{ r.error }}</div> }
          </div>
        } @empty {
          <div class="vnr-eft__empty">{{ emptyText() }}</div>
        }
        @for (t of totals(); track t.key) {
          <div class="vnr-eft__ct"><span>{{ labelOf(t.key) }}</span><b>{{ fmt(t.value) }}</b></div>
        }
      </div>

      @if (!readonly()) {
        <div class="vnr-eft__ft">
          <button type="button" class="vnr-eft__add" (click)="addRow.emit()">+ {{ addLabel() }}</button>
        </div>
      }
    </div>
  `,
  styles: [`
    /* Host mới là grid item của .vnr-fg (KHÔNG phải .vnr-eft bên trong).
       Đặt grid-column lên div con sẽ im lặng không có tác dụng. */
    vnr-editable-form-table { display: block; min-inline-size: 0; }
    .vnr-fg > vnr-editable-form-table { grid-column: 1 / -1; }

    .vnr-eft__tb { inline-size: 100%; border-collapse: collapse; border: 1px solid var(--border-sub);
      border-radius: var(--radius-sm, 6px); overflow: hidden; background: var(--bg-surface); }
    .vnr-eft__tb th { background: var(--bg-surface-subtle); font-size: var(--fs-11, 11px);
      text-transform: uppercase; letter-spacing: .3px; color: var(--text-soft); font-weight: var(--font-semibold, 600);
      text-align: start; padding: var(--space-2, 8px) var(--space-2-5, 10px);
      border-block-end: 1px solid var(--border-soft); white-space: nowrap; }
    .vnr-eft__tb td { padding: var(--space-1, 4px) var(--space-2-5, 10px); font-size: var(--fs-12, 12px);
      color: var(--text-body); border-block-end: 1px solid var(--border-soft); }
    .vnr-eft__tb th.ix, .vnr-eft__tb td.ix { inline-size: 34px; text-align: center; color: var(--text-soft);
      font-variant-numeric: tabular-nums; }
    .vnr-eft__tb th.ac, .vnr-eft__tb td.ac { inline-size: 66px; text-align: center; white-space: nowrap; }
    /* Cột số căn phải + tabular-nums ⇒ hàng đơn vị thẳng cột, so sánh được bằng mắt */
    .vnr-eft__tb th[data-align='end'], .vnr-eft__tb td[data-align='end'] { text-align: end; }
    .vnr-eft__tb td[data-align='end'], .vnr-eft__in[data-align='end'],
    .vnr-eft__ro[data-align='end'] { font-variant-numeric: tabular-nums; }
    .vnr-eft__tb tbody tr:hover { background: var(--bg-surface-subtle); }

    /* Dòng lỗi: nền cảnh báo + CHỮ lỗi ngay dưới ⇒ đọc được cả khi không phân biệt màu */
    .vnr-eft__tb tr.has-err { background: var(--error-bg); }
    .vnr-eft__tb tr.has-err:hover { background: var(--error-bg); }
    .vnr-eft__er td { background: var(--error-bg); color: var(--error-base);
      font-size: var(--fs-11, 11px); font-weight: var(--font-semibold, 600); padding-block: var(--space-1, 4px);
      padding-block-end: var(--space-2, 8px); }

    .vnr-eft__ro { display: inline-block; padding-block: 5px; color: var(--text-strong); }
    .vnr-eft__in { inline-size: 100%; block-size: 28px; border: 1px solid transparent; border-radius: var(--radius-xs, 4px);
      background: transparent; padding: 0 6px; font: inherit; font-size: var(--fs-12, 12px); color: var(--text-strong); }
    .vnr-eft__in[data-align='end'] { text-align: end; }
    .vnr-eft__in:hover { border-color: var(--border-sub); background: var(--bg-surface); }
    .vnr-eft__in:focus-visible { outline: 2px solid var(--primary-base); outline-offset: 1px; }
    .vnr-eft__in:focus { outline: none; border-color: var(--primary-base); background: var(--bg-surface); }

    .vnr-eft__tb tfoot td { background: var(--bg-surface-subtle);
      border-block-start: 1px solid var(--border-sub); border-block-end: none;
      padding-block: var(--space-2, 8px); }
    .vnr-eft__tb tfoot .tv { font-weight: var(--font-bold, 700); color: var(--text-strong); font-variant-numeric: tabular-nums; }
    .vnr-eft__tb tfoot .tl { font-weight: var(--font-bold, 700); color: var(--text-strong); }

    .vnr-eft__b { border: none; background: none; color: var(--text-soft); font: inherit;
      font-size: var(--fs-11, 11px); cursor: pointer; border-radius: var(--radius-xs, 4px); padding: 3px 6px; }
    .vnr-eft__b:hover { background: var(--primary-bg-subtle); color: var(--primary-base); }
    .vnr-eft__b.is-danger:hover { background: var(--error-bg); color: var(--error-base); }
    .vnr-eft__empty { text-align: center; color: var(--text-soft); padding: var(--space-4, 16px);
      font-size: var(--fs-12, 12px); }
    .vnr-eft__ft { padding-block-start: var(--space-2, 8px); }
    .vnr-eft__add { border: 1px dashed var(--border-strong); background: none;
      color: var(--text-body); border-radius: var(--radius-sm, 6px); padding: 6px var(--space-3, 12px);
      font: inherit; font-size: var(--fs-12, 12px); cursor: pointer; }
    .vnr-eft__add:hover { border-color: var(--primary-base); color: var(--primary-base); }

    .vnr-eft__cards { display: none; flex-direction: column; gap: var(--space-2, 8px); }
    .vnr-eft__card { border: 1px solid var(--border-sub); border-radius: var(--radius-sm, 6px);
      background: var(--bg-surface); overflow: hidden; }
    .vnr-eft__card.has-err { border-color: var(--error-base); background: var(--error-bg); }
    .vnr-eft__card .hd { display: flex; align-items: center; gap: var(--space-2, 8px);
      padding: 6px var(--space-2-5, 10px); background: var(--bg-surface-subtle);
      border-block-end: 1px solid var(--border-soft); }
    .vnr-eft__card .hd .ix { inline-size: 20px; block-size: 20px; border-radius: var(--radius-full);
      background: var(--bg-surface); border: 1px solid var(--border-sub);
      display: inline-flex; align-items: center; justify-content: center; font-size: var(--fs-11, 11px);
      font-weight: var(--font-semibold, 600); color: var(--text-sub); flex: none; font-variant-numeric: tabular-nums; }
    .vnr-eft__card .hd .sp { margin-inline-start: auto; }
    .vnr-eft__card .bd { display: flex; flex-direction: column; gap: var(--space-2, 8px);
      padding: var(--space-2-5, 10px); }
    .vnr-eft__card .fl { display: flex; flex-direction: column; gap: 3px; }
    .vnr-eft__card .lb { font-size: var(--fs-11, 11px); font-weight: var(--font-medium, 500); color: var(--text-sub); }
    .vnr-eft__card .fl .vnr-eft__in { border-color: var(--border-sub); background: var(--bg-surface);
      block-size: 30px; }
    .vnr-eft__card .er { padding: 6px var(--space-2-5, 10px); background: var(--error-bg);
      color: var(--error-base); font-size: var(--fs-11, 11px); font-weight: var(--font-semibold, 600); }
    .vnr-eft__ct { display: flex; justify-content: space-between; align-items: baseline;
      padding: var(--space-2-5, 10px); background: var(--bg-surface-subtle);
      border: 1px solid var(--border-sub); border-radius: var(--radius-sm, 6px);
      font-size: var(--fs-12, 12px); color: var(--text-sub); }
    .vnr-eft__ct b { color: var(--text-strong); font-variant-numeric: tabular-nums; }

    /* Đổi vai theo BỀ RỘNG CONTAINER (không phải viewport) — hẹp thì đổ thẻ, không cuộn ngang.
       (Lưu ý: KHÔNG đặt dấu backtick trong comment CSS — nó đóng template literal sớm,
        biến styles thành mảng nhiều phần tử ⇒ lỗi "Failed to resolve styles at position 1".) */
    @container vnrform (max-width: 559px) {
      .vnr-eft__tb { display: none; }
      .vnr-eft__cards { display: flex; }
    }
  `],
})
export class VnrEditableFormTable {
  readonly columns = input.required<readonly VnrFormTableColumn[]>();
  readonly rows = input.required<readonly VnrFormTableRow[]>();
  /** Dòng tổng ĐÃ TÍNH bên ngoài — component không cộng lại. */
  readonly totals = input<readonly VnrFormTableTotal[]>([]);
  readonly readonly = input(false);
  readonly addLabel = input('Thêm dòng');
  readonly totalLabel = input('Tổng cộng');
  readonly emptyText = input('Chưa có dòng nào.');

  readonly cellChange = output<VnrFormTableCellChange>();
  readonly addRow = output<void>();
  readonly removeRow = output<string>();
  readonly duplicateRow = output<string>();

  /** Tra nhanh tổng theo khoá cột — chỉ TRA CỨU, không tính. */
  private readonly totalMap = computed(() => {
    const m = new Map<string, VnrFormTableCellValue>();
    for (const t of this.totals()) m.set(t.key, t.value);
    return m;
  });

  private readonly labelMap = computed(() => {
    const m = new Map<string, string>();
    for (const c of this.columns()) m.set(c.key, c.label);
    return m;
  });

  /** Số ô của một hàng đầy đủ: cột STT + các cột dữ liệu + cột thao tác. */
  protected colSpan(): number {
    return 1 + this.columns().length + (this.readonly() ? 0 : 1);
  }

  protected alignOf(c: VnrFormTableColumn): VnrFormTableAlign {
    return c.align ?? (c.type === 'number' ? 'end' : 'start');
  }

  protected widthOf(c: VnrFormTableColumn): string | null {
    const w = c.width;
    if (w == null || w === '') return null;
    return typeof w === 'number' ? `${w}px` : w;
  }

  protected labelOf(key: string): string {
    return this.labelMap().get(key) ?? key;
  }

  /** Giá trị thô để đổ vào input (không định dạng, tránh phá thao tác gõ). */
  protected raw(row: VnrFormTableRow, key: string): VnrFormTableCellValue {
    const v = row.cells[key];
    return v === undefined ? null : v;
  }

  protected totalOf(key: string): VnrFormTableCellValue {
    const v = this.totalMap().get(key);
    return v === undefined ? null : v;
  }

  /** Chỉ ĐỊNH DẠNG hiển thị — không phải tính toán nghiệp vụ. */
  protected display(row: VnrFormTableRow, c: VnrFormTableColumn): string {
    return this.fmt(this.raw(row, c.key)) || '—';
  }

  protected fmt(v: VnrFormTableCellValue): string {
    if (v == null || v === '') return '';
    return typeof v === 'number' ? new Intl.NumberFormat('vi-VN').format(v) : String(v);
  }

  protected onCell(rowId: string, c: VnrFormTableColumn, e: Event): void {
    const text = (e.target as HTMLInputElement).value;
    const value: VnrFormTableCellValue =
      c.type === 'number' ? (text === '' ? null : Number(text)) : text;
    this.cellChange.emit({ rowId, key: c.key, value });
  }
}

// ══════════════════════════════════════════════════════════════════════════════
// LAYOUT · checklist — danh sách việc phải làm có phụ thuộc
// ══════════════════════════════════════════════════════════════════════════════

export type VnrChecklistStatus = 'todo' | 'doing' | 'done' | 'blocked';

export interface VnrChecklistTask {
  readonly id: string;
  readonly title: string;
  readonly assignee?: string | null;
  /** Chuỗi ngày ĐÃ ĐỊNH DẠNG bởi caller — UI không parse, không so sánh ngày. */
  readonly dueDate?: string | null;
  readonly status: VnrChecklistStatus;
  /** Bắt buộc phải xong mới được chốt quy trình. */
  readonly required?: boolean;
  /** Id việc phải xong trước. Chưa xong ⇒ việc này hiện lý do chờ. */
  readonly dependsOn?: string | null;
  readonly note?: string | null;
}

/** Dòng hiển thị đã suy diễn sẵn — giữ template gọn, không nhét logic vào HTML. */
export interface VnrChecklistTaskView {
  readonly task: VnrChecklistTask;
  readonly statusLabel: string;
  /** Lý do chưa làm được, viết bằng CHỮ. Null = không vướng gì. */
  readonly blockedReason: string | null;
  /** Ghi chú hiển thị riêng (khi chưa bị gộp vào lý do chặn). */
  readonly showNote: boolean;
  /** Bắt buộc nhưng chưa xong ⇒ cần dấu hiệu riêng. */
  readonly requiredPending: boolean;
}

/**
 * Danh sách việc phải làm theo quy trình (layout `checklist`).
 *
 * RANH GIỚI: component KHÔNG tự quyết việc nào tới hạn, KHÔNG tự chuyển trạng thái,
 * KHÔNG tự gán người. Nó chỉ ĐẾM để hiển thị tiến độ và TRA phụ thuộc trong chính
 * danh sách được truyền vào, rồi bắn event ra cho tầng nghiệp vụ xử lý.
 * ⇒ Dùng lại được cho: onboarding · offboarding · bàn giao công việc · chuẩn bị hợp đồng ·
 *   kiểm tra hồ sơ · chuẩn bị đợt đánh giá.
 */
@Component({
  selector: 'vnr-checklist-group',
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  imports: [HrmProgress, HrmAlert],
  template: `
    <div class="vnr-ckl">
      <div class="vnr-ckl__hd">
        <span class="t">{{ title() }}</span>
        <!-- Tiến độ: chỉ ĐẾM để hiển thị, không phải luật nghiệp vụ -->
        <span class="pg">{{ doneCount() }}/{{ totalCount() }} hoàn thành</span>
      </div>
      <!-- Thanh tiến độ dùng component design system; số liệu "x/y" đã hiện ở trên ⇒ tắt showInfo -->
      <hrm-progress
        [percent]="percent()"
        [status]="percent() === 100 ? 'success' : 'active'"
        [showInfo]="false"
        type="line"
        size="small" />
      <!-- Cảnh báo dùng hrm-alert (có icon) cho ĐỒNG NHẤT với mọi cảnh báo khác trong màn hình;
           hộp tự vẽ trước đây chỉ có màu + chữ đậm, không icon, nên trông lệch chuẩn khi đặt cạnh alert thật. -->
      @if (requiredPendingCount() > 0) {
        <div role="status" aria-live="polite">
          <hrm-alert type="warning"
            [message]="'Còn ' + requiredPendingCount() + ' việc bắt buộc chưa hoàn thành — chưa thể chốt quy trình.'" />
        </div>
      }

      <ul class="vnr-ckl__ls">
        @for (v of view(); track v.task.id) {
          <li class="vnr-ckl__it" [attr.data-st]="v.task.status"
            [class.is-blocked]="!!v.blockedReason" [class.is-req]="v.requiredPending">
            <button type="button" class="ck" [attr.data-st]="v.task.status"
              [disabled]="readonly() || !!v.blockedReason"
              [attr.aria-pressed]="v.task.status === 'done'"
              [attr.aria-label]="'Đánh dấu hoàn thành: ' + v.task.title"
              (click)="toggle.emit(v.task.id)">
              @if (v.task.status === 'done') { <span class="mk">✓</span> }
              @else if (v.task.status === 'doing') { <span class="mk">•</span> }
              @else if (v.task.status === 'blocked') { <span class="mk">!</span> }
            </button>

            <div class="bd">
              <div class="ti">
                <span class="tx">{{ v.task.title }}</span>
                @if (v.requiredPending) { <span class="rq">Bắt buộc</span> }
                @else if (v.task.required) { <span class="rq is-ok">Bắt buộc · đã xong</span> }
                <span class="st" [attr.data-st]="v.task.status">{{ v.statusLabel }}</span>
              </div>
              <div class="mt">
                @if (v.task.assignee) { <span>Phụ trách: <b>{{ v.task.assignee }}</b></span> }
                @else { <span class="none">Chưa giao người phụ trách</span> }
                @if (v.task.dueDate) { <span>Hạn: <b>{{ v.task.dueDate }}</b></span> }
              </div>
              <!-- Lý do chưa làm được luôn viết bằng CHỮ, không chỉ đổi màu -->
              @if (v.blockedReason) { <div class="bl">{{ v.blockedReason }}</div> }
              @if (v.showNote) { <div class="nt">{{ v.task.note }}</div> }
            </div>

            @if (!readonly()) {
              <div class="ac">
                <button type="button" class="vnr-ckl__b" (click)="assign.emit(v.task.id)">
                  {{ v.task.assignee ? 'Đổi người' : 'Giao việc' }}
                </button>
                <button type="button" class="vnr-ckl__b is-danger" aria-label="Xoá việc"
                  (click)="remove.emit(v.task.id)">✕</button>
              </div>
            }
          </li>
        } @empty {
          <li class="vnr-ckl__empty">{{ emptyText() }}</li>
        }
      </ul>

      @if (!readonly()) {
        <button type="button" class="vnr-ckl__add" (click)="add.emit()">+ {{ addLabel() }}</button>
      }
    </div>
  `,
  styles: [`
    /* Host là grid item của .vnr-fg — chiếm trọn hàng, không đặt grid-column lên div con */
    vnr-checklist-group { display: block; min-inline-size: 0; }
    .vnr-fg > vnr-checklist-group { grid-column: 1 / -1; }

    .vnr-ckl { display: flex; flex-direction: column; gap: var(--space-2, 8px); }
    .vnr-ckl__hd { display: flex; align-items: baseline; gap: var(--space-2, 8px); }
    .vnr-ckl__hd .t { font-size: var(--fs-13, 13px); font-weight: var(--font-semibold, 600); color: var(--text-strong); }
    .vnr-ckl__hd .pg { margin-inline-start: auto; font-size: var(--fs-12, 12px); color: var(--text-sub);
      font-variant-numeric: tabular-nums; }

    .vnr-ckl__ls { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column;
      gap: var(--space-2, 8px); }
    .vnr-ckl__it { display: flex; align-items: flex-start; gap: var(--space-2-5, 10px);
      border: 1px solid var(--border-sub); border-radius: var(--radius-sm, 6px);
      background: var(--bg-surface); padding: var(--space-2, 8px) var(--space-2-5, 10px); }
    .vnr-ckl__it[data-st='done'] { background: var(--bg-surface-subtle); }
    .vnr-ckl__it[data-st='done'] .tx { color: var(--text-soft); text-decoration: line-through; }
    .vnr-ckl__it.is-blocked { border-color: var(--warning-border);
      background: var(--warning-bg); }
    .vnr-ckl__it.is-req { border-inline-start: 3px solid var(--warning-base); }

    .vnr-ckl__it .ck { flex: none; inline-size: 20px; block-size: 20px; margin-block-start: 1px;
      border: 1px solid var(--border-strong); border-radius: var(--radius-xs, 4px);
      background: var(--bg-surface); color: var(--text-soft); cursor: pointer;
      display: inline-flex; align-items: center; justify-content: center;
      font: inherit; font-size: var(--fs-12, 12px); line-height: 1; padding: 0; }
    .vnr-ckl__it .ck:hover:not(:disabled) { border-color: var(--primary-base);
      color: var(--primary-base); }
    .vnr-ckl__it .ck:disabled { cursor: not-allowed; }
    .vnr-ckl__it .ck[data-st='done'] { background: var(--success-base);
      border-color: var(--success-base); color: var(--text-on-primary); }
    .vnr-ckl__it .ck[data-st='doing'] { border-color: var(--primary-base);
      color: var(--primary-base); }
    .vnr-ckl__it .ck[data-st='blocked'] { border-color: var(--warning-base);
      color: var(--warning-base); font-weight: var(--font-bold, 700); }

    .vnr-ckl__it .bd { flex: 1 1 auto; min-inline-size: 0; }
    .vnr-ckl__it .ti { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; }
    .vnr-ckl__it .tx { font-size: var(--fs-13, 13px); font-weight: var(--font-medium, 500); color: var(--text-strong);
      word-break: break-word; }
    .vnr-ckl__it .rq { font-size: var(--fs-11, 11px); font-weight: var(--font-semibold, 600); border-radius: var(--radius-full); padding: 1px 8px;
      color: var(--warning-base); background: var(--warning-bg); }
    .vnr-ckl__it .rq.is-ok { color: var(--success-base); background: var(--success-bg); }
    .vnr-ckl__it .st { margin-inline-start: auto; font-size: var(--fs-11, 11px); font-weight: var(--font-semibold, 600);
      border-radius: var(--radius-full); padding: 1px 8px; color: var(--text-sub); background: var(--faded-bg); }
    .vnr-ckl__it .st[data-st='doing'] { color: var(--info-base);
      background: var(--info-bg); }
    .vnr-ckl__it .st[data-st='done'] { color: var(--success-base); background: var(--success-bg); }
    .vnr-ckl__it .st[data-st='blocked'] { color: var(--warning-base); background: var(--warning-bg); }
    .vnr-ckl__it .mt { display: flex; flex-wrap: wrap; gap: var(--space-3, 12px); margin-block-start: 3px;
      font-size: var(--fs-11, 11px); color: var(--text-sub); }
    .vnr-ckl__it .mt b { color: var(--text-body); font-variant-numeric: tabular-nums; }
    .vnr-ckl__it .mt .none { color: var(--text-soft); font-style: italic; }
    .vnr-ckl__it .bl { margin-block-start: 4px; font-size: var(--fs-11, 11px); font-weight: var(--font-semibold, 600);
      color: var(--warning-base); }
    .vnr-ckl__it .nt { margin-block-start: 4px; font-size: var(--fs-11, 11px); color: var(--text-soft); }
    .vnr-ckl__it .ac { flex: none; display: flex; align-items: center; gap: 2px; }

    .vnr-ckl__b { border: none; background: none; color: var(--text-sub); font: inherit;
      font-size: var(--fs-11, 11px); cursor: pointer; border-radius: var(--radius-xs, 4px); padding: 3px 7px; }
    .vnr-ckl__b:hover { background: var(--primary-bg-subtle); color: var(--primary-base); }
    .vnr-ckl__b.is-danger:hover { background: var(--error-bg); color: var(--error-base); }
    .vnr-ckl__empty { text-align: center; color: var(--text-soft); font-size: var(--fs-12, 12px);
      padding: var(--space-4, 16px); border: 1px dashed var(--border-strong);
      border-radius: var(--radius-sm, 6px); }
    .vnr-ckl__add { align-self: flex-start; border: 1px dashed var(--border-strong);
      background: none; color: var(--text-body); border-radius: var(--radius-sm, 6px);
      padding: 6px var(--space-3, 12px); font: inherit; font-size: var(--fs-12, 12px); cursor: pointer; }
    .vnr-ckl__add:hover { border-color: var(--primary-base); color: var(--primary-base); }

    /* Container hẹp ⇒ nút thao tác xuống dòng, tiêu đề không bị bóp */
    @container vnrform (max-width: 559px) {
      .vnr-ckl__it { flex-wrap: wrap; }
      .vnr-ckl__it .st { margin-inline-start: 0; }
      .vnr-ckl__it .ac { inline-size: 100%; justify-content: flex-end;
        border-block-start: 1px dashed var(--border-sub); padding-block-start: 6px; }
    }
  `],
})
export class VnrChecklistGroup {
  readonly tasks = input.required<readonly VnrChecklistTask[]>();
  readonly readonly = input(false);
  readonly title = input('Danh sách công việc');
  readonly addLabel = input('Thêm công việc');
  readonly emptyText = input('Chưa có công việc nào.');

  readonly toggle = output<string>();
  readonly assign = output<string>();
  readonly remove = output<string>();
  readonly add = output<void>();

  /** ĐẾM để hiển thị tiến độ — được phép, đây không phải luật nghiệp vụ. */
  protected readonly totalCount = computed(() => this.tasks().length);
  protected readonly doneCount = computed(() => this.tasks().filter((t) => t.status === 'done').length);
  protected readonly percent = computed(() => {
    const total = this.totalCount();
    return total === 0 ? 0 : Math.round((this.doneCount() / total) * 100);
  });
  protected readonly requiredPendingCount = computed(
    () => this.tasks().filter((t) => t.required && t.status !== 'done').length,
  );

  /** Suy diễn hiển thị: nhãn trạng thái + lý do bị chặn (tra trong chính danh sách truyền vào). */
  protected readonly view = computed<readonly VnrChecklistTaskView[]>(() => {
    const all = this.tasks();
    const byId = new Map<string, VnrChecklistTask>(all.map((t) => [t.id, t]));

    return all.map((task) => {
      let blockedReason: string | null = null;

      if (task.status !== 'done') {
        if (task.status === 'blocked') {
          blockedReason = task.note
            ? `Đang bị chặn: ${task.note}`
            : 'Đang bị chặn — chưa thể thực hiện.';
        } else if (task.dependsOn) {
          const dep = byId.get(task.dependsOn);
          if (!dep) {
            blockedReason = `Chờ một công việc phụ thuộc không còn trong danh sách (mã ${task.dependsOn}).`;
          } else if (dep.status !== 'done') {
            blockedReason = `Chờ hoàn thành trước: ${dep.title}.`;
          }
        }
      }

      return {
        task,
        statusLabel: this.statusLabel(task.status),
        blockedReason,
        showNote: !!task.note && task.status !== 'blocked',
        requiredPending: !!task.required && task.status !== 'done',
      };
    });
  });

  private statusLabel(s: VnrChecklistStatus): string {
    switch (s) {
      case 'done': return 'Hoàn thành';
      case 'doing': return 'Đang làm';
      case 'blocked': return 'Bị chặn';
      default: return 'Chưa làm';
    }
  }
}

// ══════════════════════════════════════════════════════════════════════════════
// NAVIGATION · form dài — nhảy giữa các section, thấy ngay chỗ còn thiếu
// ══════════════════════════════════════════════════════════════════════════════

export type VnrFormNavState = 'empty' | 'partial' | 'complete' | 'error' | 'locked';

export interface VnrFormNavSection {
  readonly id: string;
  readonly label: string;
  readonly state: VnrFormNavState;
  /** Mức hoàn thiện đã tính sẵn, vd "6/7". */
  readonly meta?: string | null;
  /** Lý do khoá — hiện bằng CHỮ khi state = 'locked'. */
  readonly lockedReason?: string | null;
}

/**
 * Cột điều hướng của form dài: mỗi section một dòng, kèm chấm trạng thái và mức hoàn thiện.
 *
 * RANH GIỚI: component KHÔNG tự chấm section nào xong / thiếu / lỗi — tầng nghiệp vụ tính
 * `state` + `meta` rồi truyền vào; component chỉ vẽ và bắn `navigate`.
 * Dính trên (sticky) để luôn thấy được bức tranh tổng khi cuộn form dài.
 */
@Component({
  selector: 'vnr-form-section-nav',
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  template: `
    <nav class="vnr-fsn" [attr.aria-label]="title()">
      @if (title()) { <div class="vnr-fsn__hd">{{ title() }}</div> }
      <ul class="vnr-fsn__ls">
        @for (s of sections(); track s.id) {
          <li class="vnr-fsn__li">
            <button type="button" class="vnr-fsn__it" [attr.data-st]="s.state"
              [class.is-active]="s.id === activeId()"
              [disabled]="s.state === 'locked'"
              [attr.aria-current]="s.id === activeId() ? 'true' : null"
              [attr.aria-label]="s.label + ' — ' + stateLabel(s.state)"
              (click)="go(s)">
              <i class="dot" [attr.data-st]="s.state" aria-hidden="true"></i>
              <span class="lb">{{ s.label }}</span>
              @if (s.meta) { <span class="mt">{{ s.meta }}</span> }
            </button>
            <!-- Trạng thái đặc biệt luôn kèm CHỮ, không chỉ dựa vào màu chấm -->
            @if (s.state === 'locked') {
              <div class="vnr-fsn__nt is-lock">{{ s.lockedReason || 'Đang khoá — cần hoàn thành phần trước.' }}</div>
            } @else if (s.state === 'error') {
              <div class="vnr-fsn__nt is-err">Có lỗi cần sửa</div>
            }
          </li>
        } @empty {
          <li class="vnr-fsn__empty">Chưa có phần nào.</li>
        }
      </ul>
    </nav>
  `,
  styles: [`
    /* Host là grid item khi đặt trong .vnr-fg — khai trên host, không phải trên nav con */
    vnr-form-section-nav { display: block; min-inline-size: 0; align-self: start; }

    /* Dính trên khi cuộn form dài (position: sticky, top: 0) */
    .vnr-fsn { position: sticky; top: 0; inset-block-start: 0; z-index: 1;
      display: flex; flex-direction: column; gap: var(--space-1, 4px);
      background: var(--bg-surface); border: 1px solid var(--border-sub);
      border-radius: var(--radius-sm, 6px); padding: var(--space-2, 8px); }
    .vnr-fsn__hd { font-size: var(--fs-11, 11px); font-weight: var(--font-semibold, 600); text-transform: uppercase;
      letter-spacing: .3px; color: var(--text-soft); padding: var(--space-1, 4px) var(--space-2, 8px); }
    .vnr-fsn__ls { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 2px; }
    .vnr-fsn__li { display: flex; flex-direction: column; }

    .vnr-fsn__it { display: flex; align-items: center; gap: var(--space-2, 8px); inline-size: 100%;
      border: none; background: none; text-align: start; cursor: pointer;
      border-radius: var(--radius-xs, 4px); padding: 6px var(--space-2, 8px);
      font: inherit; font-size: var(--fs-12, 12px); color: var(--text-body); }
    .vnr-fsn__it:hover:not(:disabled) { background: var(--bg-surface-subtle); color: var(--text-strong); }
    .vnr-fsn__it.is-active { background: var(--primary-bg-subtle); color: var(--primary-base);
      font-weight: var(--font-semibold, 600); }
    .vnr-fsn__it:disabled { cursor: not-allowed; color: var(--text-soft); }
    .vnr-fsn__it .lb { flex: 1 1 auto; min-inline-size: 0; overflow: hidden; text-overflow: ellipsis;
      white-space: nowrap; }
    .vnr-fsn__it .mt { flex: none; font-size: var(--fs-11, 11px); color: var(--text-soft);
      font-variant-numeric: tabular-nums; }
    .vnr-fsn__it.is-active .mt { color: var(--primary-base); }

    .vnr-fsn__it .dot { flex: none; inline-size: 8px; block-size: 8px; border-radius: var(--radius-full);
      border: 1px solid var(--border-strong); background: var(--bg-surface); }
    .vnr-fsn__it .dot[data-st='partial']  { background: var(--warning-base); border-color: var(--warning-base); }
    .vnr-fsn__it .dot[data-st='complete'] { background: var(--success-base); border-color: var(--success-base); }
    .vnr-fsn__it .dot[data-st='error']    { background: var(--error-base); border-color: var(--error-base); }
    .vnr-fsn__it .dot[data-st='locked']   { background: var(--faded-base); border-color: var(--faded-base); }

    .vnr-fsn__nt { font-size: var(--fs-11, 11px); font-weight: var(--font-medium, 500);
      padding: 0 var(--space-2, 8px) var(--space-1, 4px) 24px; }
    .vnr-fsn__nt.is-lock { color: var(--text-soft); }
    .vnr-fsn__nt.is-err { color: var(--error-base); font-weight: var(--font-semibold, 600); }
    .vnr-fsn__empty { font-size: var(--fs-12, 12px); color: var(--text-soft);
      padding: var(--space-2, 8px); text-align: center; }

    /* Container hẹp ⇒ chuyển thành dải ngang cuộn được, vẫn dính trên */
    @container vnrform (max-width: 559px) {
      .vnr-fsn__ls { flex-direction: row; overflow-x: auto; gap: var(--space-1, 4px); }
      .vnr-fsn__li { flex: none; }
      .vnr-fsn__it .lb { white-space: nowrap; }
      .vnr-fsn__nt { display: none; }
    }
  `],
})
export class VnrFormSectionNav {
  readonly sections = input.required<readonly VnrFormNavSection[]>();
  readonly activeId = input<string | null>(null);
  readonly title = input('Nội dung form');
  readonly navigate = output<string>();

  protected go(s: VnrFormNavSection): void {
    if (s.state === 'locked') return;
    this.navigate.emit(s.id);
  }

  /** Nhãn trạng thái đọc được bằng CHỮ — phục vụ aria-label và trình đọc màn hình. */
  protected stateLabel(s: VnrFormNavState): string {
    switch (s) {
      case 'complete': return 'Đã hoàn thành';
      case 'partial': return 'Đang nhập dở';
      case 'error': return 'Có lỗi';
      case 'locked': return 'Đang khoá';
      default: return 'Chưa nhập';
    }
  }
}
